t.script:
(function() {
    var liffId = '';
    var target = '';

    // 新·2：跟 controllers/liff_redirect.py 的
    // LiffRedirectController.REDIRECT_TARGETS 保持一致，
    // 那才是唯一真相來源。這裡是靜態 QWeb 模板，沒有管道
    // 在 render 當下讀到 line.liff.config.rebook_path，
    // book 只能先用跟 REDIRECT_TARGETS 一樣的安全預設值；
    // 若這個模板實際上有在使用，需要讓渲染它的 controller
    // 把 rebook_path 解析後的值透過 render context 傳進來
    // （目前在我負責的三個檔案裡找不到任何地方呼叫
    // woow_odoo_line_liff.liff_redirect_bridge 這個模板，
    // 已在 FIXES.md 註記，需要確認這份模板是否還在使用）。
    // 直接跳轉對照表（fallback）
    var DIRECT_URLS = {
        'book': '/my/home',
        'my-bookings': '/my/ext-bookings',
        'profile': '/my/account',
        'home': '/my/home',
        'orders': '/my/orders',
        'invoices': '/my/invoices'
    };

    function setStatus(text) {
        var el = document.getElementById('liff-status-text');
        if (el) el.textContent = text;
    }

    function postToken(idToken) {
        var form = document.createElement('form');
        form.method = 'POST';
        form.action = '/liff/redirect/' + target;
        var input = document.createElement('input');
        input.type = 'hidden';
        input.name = 'id_token';
        input.value = idToken;
        form.appendChild(input);
        document.body.appendChild(form);
        form.submit();
    }

    function fallback() {
        // 無法取得 token，直接跳轉目標頁面
        var url = DIRECT_URLS[target] || '/my/home';
        setStatus('正在跳轉...');
        window.location.href = url;
    }

    if (!liffId) {
        setStatus('設定錯誤');
        return;
    }

    if (typeof liff === 'undefined') {
        setStatus('SDK 載入失敗');
        fallback();
        return;
    }

    liff.init({ liffId: liffId }).then(function() {
        console.log('[Bridge] init OK, loggedIn=' + liff.isLoggedIn());

        if (!liff.isLoggedIn()) {
            // 未登入 → 不呼叫 liff.login()，直接 fallback
            setStatus('正在跳轉...');
            fallback();
            return;
        }

        // 取得 ID Token
        var idToken = null;
        try {
            idToken = liff.getIDToken();
        } catch(e) {
            console.warn('[Bridge] getIDToken error', e);
        }

        if (idToken) {
            setStatus('登入成功，跳轉中...');
            postToken(idToken);
        } else {
            // 有登入但無 token（可能 scope 缺 openid）
            setStatus('正在跳轉...');
            fallback();
        }
    }).catch(function(err) {
        console.error('[Bridge] init failed', err);
        setStatus('正在跳轉...');
        fallback();
    });
})();
